function clone(o){return JSON.parse(JSON.stringify(o))} function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]))} function money(n){return 'KES '+Number(n||0).toLocaleString('en-KE')} function uid(prefix){return prefix+'-'+Date.now().toString(36).toUpperCase()}
function getData(){let saved;try{saved=JSON.parse(localStorage.getItem('gldcDemoData')||'null')}catch(e){};const d=clone(DEFAULT_DATA);if(saved){for(const k of Object.keys(saved))d[k]=saved[k];d.content={...DEFAULT_CONTENT,...(saved.content||{})}}else localStorage.setItem('gldcDemoData',JSON.stringify(d));return d}
function saveData(d){localStorage.setItem('gldcDemoData',JSON.stringify(d))} function addAudit(action,entity,result='SUCCESS'){const d=getData();d.audit.unshift({time:new Date().toLocaleString(),user:'Demo Admin',action,entity,result});d.audit=d.audit.slice(0,200);saveData(d)}
function toast(msg){let t=document.getElementById('toast');if(!t){t=document.createElement('div');t.id='toast';t.className='toast';document.body.appendChild(t)}t.textContent=msg;t.classList.add('show');clearTimeout(window.__toast);window.__toast=setTimeout(()=>t.classList.remove('show'),3000)}
function statusPill(s){const x=String(s||'').toUpperCase();let c='gray';if(['APPROVED','PUBLISHED','ACTIVE','SUCCESSFUL','PAID','COMPLETED','WON'].includes(x))c='green';else if(['NEW','PENDING','PROCESSING','REVIEW','MEMBER_SUBMITTED','SENT','PARTIALLY PAID','DESIGN','IN PROGRESS'].includes(x))c='orange';else if(['REJECTED','FAILED','CANCELLED','BLOCKED','OVERDUE'].includes(x))c='red';return `<span class="pill ${c}">${esc(s)}</span>`}
function waUrl(text='Hello GLDC, I would like to make an enquiry.'){const d=getData();return `https://wa.me/${d.settings.whatsapp}?text=${encodeURIComponent(text)}`}
function navHeader(){const d=getData(),p=location.pathname.split('/').pop()||'index.html',member=d.membership.enabled;return `<header class="site-header"><div class="container navbar"><a href="index.html"><img class="logo" src="assets/gldc-logo.png" alt="GLDC logo"></a><button class="menu-btn" id="menuBtn" aria-expanded="false">☰</button><nav class="nav-links" id="navLinks"><a class="${p==='index.html'?'active':''}" href="index.html">Home</a><a href="about.html">About</a><a href="services.html">Services</a><a href="projects.html">Projects</a><a href="team.html">Team</a><a href="testimonials.html">Testimonials</a><a href="service-areas.html">Areas</a><a href="contact.html">Contact</a>${member?'<a class="member-link" href="member.html">'+esc(d.membership.buttonLabel)+'</a>':''}<a class="btn primary small nav-cta" href="quote.html">REQUEST A QUOTE</a></nav></div></header>`}
function footer(){const d=getData();return `<footer class="site-footer"><div class="container footer-grid"><div><img src="assets/gldc-logo.png" alt="GLDC" style="width:220px;background:#fff;padding:6px;border-radius:8px;margin-bottom:18px"><p>${esc(d.content['footer.description'])}</p><p><strong style="color:#fff">${esc(d.settings.tagline)}</strong></p></div><div><div class="footer-title">Company</div><p><a href="about.html">About</a></p><p><a href="projects.html">Projects</a></p><p><a href="team.html">Team</a></p><p><a href="contact.html">Contact</a></p></div><div><div class="footer-title">Services</div>${d.services.filter(s=>s.published).slice(0,4).map(s=>`<p><a href="service-detail.html?id=${encodeURIComponent(s.id)}">${esc(s.name)}</a></p>`).join('')}</div><div><div class="footer-title">Contact</div><p>${esc(d.settings.phone)}</p><p>${esc(d.settings.email)}</p><p>${esc(d.settings.location)}</p><p><a target="_blank" rel="noopener" href="${waUrl()}">WhatsApp</a></p></div></div><div class="container footer-bottom"><span>© ${new Date().getFullYear()} ${esc(d.settings.company)}</span><span><a href="privacy.html">Privacy</a> · <a href="terms.html">Terms</a></span></div></footer><a class="whatsapp" target="_blank" rel="noopener" href="${waUrl()}">CHAT WITH US ON WHATSAPP</a>`}
function shell(inner){document.body.innerHTML=navHeader()+inner+footer()+'<div id="toast" class="toast"></div>';const b=document.getElementById('menuBtn'),n=document.getElementById('navLinks');if(b)b.onclick=()=>{n.classList.toggle('open');b.setAttribute('aria-expanded',n.classList.contains('open'))}}
function pageHero(key,eyebrow='GLDC'){const d=getData();return `<section class="page-hero"><div class="container"><div class="breadcrumb"><a href="index.html">Home</a> / ${esc(eyebrow)}</div><span class="eyebrow">${esc(eyebrow)}</span><h1>${esc(d.content[key+'.hero.title'])}</h1><p>${esc(d.content[key+'.hero.body'])}</p></div></section>`}
function publishedSections(page){const d=getData();return d.sections.filter(s=>s.page===page&&s.published).map(s=>`<section class="section ${s.variant==='alt'?'alt':''}"><div class="container ${s.layout==='split'?'grid grid-2':''}" style="align-items:center">${s.image?`<img class="responsive-media" src="${esc(s.image)}" alt="${esc(s.alt||s.title)}">`:''}<div><span class="eyebrow">${esc(s.eyebrow||'GLDC')}</span><h2>${esc(s.title)}</h2><p>${esc(s.body)}</p>${s.buttonText?`<a class="btn primary" href="${esc(s.buttonUrl||'quote.html')}">${esc(s.buttonText)}</a>`:''}</div></div></section>`).join('')}
function homePage(){const d=getData(),services=d.services.filter(s=>s.published),projects=d.projects.filter(p=>p.published&&p.approved);shell(`<section class="hero"><img class="hero-bg" src="${esc(d.content['home.hero.image']||DEFAULT_IMAGES.hero)}" alt="GLDC development placeholder"><div class="container hero-content"><span class="eyebrow">${esc(d.content['home.hero.eyebrow'])}</span><h1>${esc(d.content['home.hero.title'])}</h1><p>${esc(d.content['home.hero.subtitle'])}</p><div class="hero-actions"><a class="btn primary" href="quote.html">${esc(d.content['home.hero.primary'])}</a><a class="btn secondary" href="projects.html">${esc(d.content['home.hero.secondary'])}</a></div></div><img class="hero-mark" src="assets/gldc-logo.png" alt=""></section><div class="stat-strip"><div class="container"><div class="stats"><div class="stat"><strong>01</strong><span>Land & Property</span></div><div class="stat"><strong>02</strong><span>Design & Planning</span></div><div class="stat"><strong>03</strong><span>Project Consultancy</span></div><div class="stat"><strong>04</strong><span>Client-Focused Delivery</span></div></div></div></div><section class="section"><div class="container"><div class="section-head"><span class="eyebrow">WHAT WE DO</span><h2>From land opportunity to development action.</h2><p>Services are controlled by the administrator and published only when approved.</p></div><div class="grid grid-4">${services.map(s=>`<article class="card hover service-card"><img class="service-thumb" src="${esc(s.image||DEFAULT_IMAGES.land)}" alt="${esc(s.name)}"><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p><a class="link" href="service-detail.html?id=${encodeURIComponent(s.id)}">Explore service →</a></article>`).join('')}</div></div></section><section class="section alt"><div class="container grid grid-2" style="align-items:center"><div><span class="eyebrow">${esc(d.content['home.about.eyebrow'])}</span><h2>${esc(d.content['home.about.title'])}</h2><p>${esc(d.content['home.about.body'])}</p><ul class="feature-list"><li>Professional expertise</li><li>Practical, client-focused solutions</li><li>Transparent communication</li><li>End-to-end consultancy approach</li></ul><a class="btn primary" href="about.html">ABOUT GLDC</a></div><div class="card image-card"><img src="${esc(d.content['home.about.image'])}" alt="GLDC project placeholder"><div class="body"><span class="tag">DESIGN • DEVELOPMENT</span><h3>A professional system built around your project journey.</h3><p>Approved project stories, member enquiries and secure documents can be managed from the console.</p></div></div></div></section><section class="section"><div class="container"><div class="section-head center"><span class="eyebrow">${esc(d.content['home.projects.eyebrow'])}</span><h2>${esc(d.content['home.projects.title'])}</h2><p>${esc(d.content['home.projects.body'])}</p></div><div class="grid grid-3">${projects.slice(0,6).map(p=>projectCard(p)).join('')||'<div class="notice">No approved public projects yet.</div>'}</div></div></section><section class="section alt"><div class="container"><div class="quote-band"><div class="grid grid-2" style="align-items:center"><div><span class="eyebrow" style="color:#ffd36a">START YOUR PROJECT</span><h2 style="color:#fff">${esc(d.content['home.cta.title'])}</h2><p>${esc(d.content['home.cta.body'])}</p></div><div class="hero-actions" style="justify-content:flex-end"><a class="btn secondary" href="quote.html">${esc(d.content['home.cta.primary'])}</a><a class="btn secondary" href="contact.html">${esc(d.content['home.cta.secondary'])}</a></div></div></div></div></section>${publishedSections('home')}`)}
function projectCard(p){return `<article class="card project-card hover"><img class="project-img" src="${esc((p.images&&p.images[0])||DEFAULT_IMAGES.building)}" alt="${esc(p.name)}"><div class="body"><div class="project-meta"><span>${esc(p.location||'KENYA')}</span><span>${esc(p.status)}</span></div><h3>${esc(p.name)}</h3><p>${esc(p.description||'Approved GLDC project record.')}</p><a class="btn small secondary" href="project-detail.html?id=${encodeURIComponent(p.id)}">VIEW DETAILS</a></div></article>`}
function aboutPage(){shell(pageHero('about','ABOUT GLDC')+`<section class="section"><div class="container grid grid-2"><div><span class="eyebrow">OUR MISSION</span><h2>${esc(getData().content['about.mission.title'])}</h2><p>${esc(getData().content['about.mission.body'])}</p></div><img class="responsive-media" src="${DEFAULT_IMAGES.office}" alt="GLDC office placeholder"></div></section>${publishedSections('about')}`)}
function servicesPage(){const d=getData();shell(pageHero('services','SERVICES')+`<section class="section"><div class="container grid grid-3">${d.services.filter(s=>s.published).map(s=>`<article class="card hover"><img class="project-img" src="${esc(s.image||DEFAULT_IMAGES.land)}" alt="${esc(s.name)}"><div class="body"><span class="tag">${esc(s.category)}</span><h3>${esc(s.name)}</h3><p>${esc(s.description)}</p><a class="btn small primary" href="service-detail.html?id=${encodeURIComponent(s.id)}">VIEW SERVICE</a></div></article>`).join('')}</div></div></section>${publishedSections('services')}`)}
function serviceDetail(){const d=getData(),id=new URLSearchParams(location.search).get('id')||d.services[0]?.id,s=d.services.find(x=>x.id===id)||d.services[0];shell(`<section class="page-hero"><div class="container"><div class="breadcrumb"><a href="services.html">Services</a> / Detail</div><span class="eyebrow">${esc(s?.category||'SERVICE')}</span><h1>${esc(s?.name||'Service')}</h1><p>${esc(s?.description||'')}</p></div></section><section class="section"><div class="container grid grid-2"><img class="responsive-media" src="${esc(s?.image||DEFAULT_IMAGES.architecture)}" alt="${esc(s?.name||'Service')}"><div><span class="badge-default">DEFAULT / EDITABLE</span><h2>Professional support for your next step.</h2><p>Use the enquiry workflow to send project details to GLDC for review.</p><a class="btn primary" href="quote.html?service=${encodeURIComponent(s?.name||'')}">REQUEST THIS SERVICE</a></div></div></section>${publishedSections('service-detail')}`)}
function projectsPage(){const d=getData();shell(pageHero('projects','PROJECTS / PORTFOLIO')+`<section class="section"><div class="container"><div class="grid grid-3">${d.projects.filter(p=>p.published&&p.approved).map(projectCard).join('')||'<div class="notice">No approved projects have been published yet.</div>'}</div></div></section>${publishedSections('projects')}`)}
function projectDetail(){const d=getData(),id=new URLSearchParams(location.search).get('id')||d.projects.find(p=>p.published&&p.approved)?.id,p=d.projects.find(x=>x.id===id);if(!p){shell(pageHero('projects','PROJECT')+'<section class="section"><div class="container"><div class="notice">Project not found or not approved for public viewing.</div></div></section>');return}shell(`<section class="page-hero"><div class="container"><div class="breadcrumb"><a href="projects.html">Projects</a> / Detail</div><span class="eyebrow">APPROVED PROJECT</span><h1>${esc(p.name)}</h1><p>${esc(p.description||'')}</p></div></section><section class="section"><div class="container"><div class="gallery">${(p.images||[]).map(x=>`<img src="${esc(x)}" alt="${esc(p.name)} project image">`).join('')}</div><div class="card" style="margin-top:22px"><span class="tag">${esc(p.status)}</span><h2>Project information</h2><p>Project value: ${money(p.value)}</p><p>Progress: ${esc(p.progress)}%</p><a class="btn primary" href="quote.html?project=${encodeURIComponent(p.id)}">ENQUIRE ABOUT A PROJECT</a></div></div></section>${publishedSections('project-detail')}`)}
function teamPage(){const d=getData();shell(pageHero('team','OUR TEAM')+`<section class="section"><div class="container grid grid-2">${d.team.filter(t=>t.published&&t.status==='APPROVED').map(t=>`<article class="card"><div style="display:flex;gap:18px;align-items:center"><img class="avatar" src="${esc(t.photo||DEFAULT_IMAGES.team)}" alt="${esc(t.name)}"><div><span class="tag">APPROVED PROFILE</span><h3>${esc(t.name)}</h3><p>${esc(t.position)}</p></div></div><hr class="sep"><p>${esc(t.qualification)}</p><p>${esc(t.bio)}</p></article>`).join('')||'<div class="notice">No approved public team profiles yet.</div>'}</div></section>${publishedSections('team')}`)}
function testimonialsPage(){const d=getData();shell(pageHero('testimonials','TESTIMONIALS')+`<section class="section"><div class="container grid grid-2">${d.testimonials.filter(t=>t.published&&t.status==='APPROVED').map(t=>`<article class="card quote-card"><span class="tag">APPROVED</span><h3>${esc(t.name)}</h3><p>“${esc(t.text)}”</p><div class="kicker">${esc(t.project)}</div></article>`).join('')||'<div class="notice">No approved testimonials yet.</div>'}</div></section>${publishedSections('testimonials')}`)}
function areasPage(){shell(pageHero('areas','SERVICE AREAS')+`<section class="section"><div class="container grid grid-3"><div class="card"><h3>Nairobi</h3><p>Planning, design and project consultancy.</p></div><div class="card"><h3>Kiambu</h3><p>Land and development support.</p></div><div class="card"><h3>Other Areas</h3><p>Contact GLDC to confirm availability.</p></div></div></div></section>${publishedSections('areas')}`)}
function contactPage(){shell(pageHero('contact','CONTACT')+`<section class="section"><div class="container grid grid-2"><div class="card"><h2>Contact GLDC</h2><p><strong>Phone:</strong> ${esc(getData().settings.phone)}</p><p><strong>Email:</strong> ${esc(getData().settings.email)}</p><p><strong>Location:</strong> ${esc(getData().settings.location)}</p><a class="btn secondary" target="_blank" href="${waUrl()}">CHAT ON WHATSAPP</a></div>${leadFormHtml('website')}</div></div></section>${publishedSections('contact')}`);bindLeadForm()}
function quotePage(){const d=getData();shell(pageHero('quote','REQUEST A QUOTE')+`<section class="section"><div class="container grid grid-2"><div><div class="notice"><strong>Review gate:</strong> enquiries are reviewed by an administrator before project approval or any money prompt.</div><h2>Project enquiry</h2><p>Provide enough detail for GLDC to assess the request.</p></div>${leadFormHtml('website')}</div></div></section>${publishedSections('quote')}`);bindLeadForm()}
function leadFormHtml(source){const d=getData();return `<form id="leadForm" class="card form-grid"><input type="hidden" name="source" value="${esc(source)}"><div class="field"><label>Full name</label><input name="name" required></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Phone</label><input name="phone" required></div><div class="field"><label>Location</label><input name="location" required></div><div class="field full"><label>Service</label><select name="service" required>${d.services.filter(s=>s.published).map(s=>`<option>${esc(s.name)}</option>`).join('')}</select></div><div class="field full"><label>Project details</label><textarea name="message" rows="6" required></textarea></div><div class="field full"><button class="btn primary">SUBMIT FOR ADMIN REVIEW</button></div></form>`}
function bindLeadForm(){const f=document.getElementById('leadForm');if(!f)return;f.onsubmit=e=>{e.preventDefault();const fd=new FormData(f),d=getData(),lead={id:'GLDC-LEAD-'+String(d.leads.length+1).padStart(4,'0'),source:fd.get('source'),memberId:'',name:fd.get('name'),email:fd.get('email'),phone:fd.get('phone'),location:fd.get('location'),service:fd.get('service'),message:fd.get('message'),status:'NEW',priority:'Normal',created:new Date().toISOString().slice(0,10)};d.leads.unshift(lead);d.notifications.unshift({id:uid('NOT'),type:'NEW ENQUIRY',channel:'IN-APP',message:`New enquiry from ${lead.name} — awaiting admin review.`,time:new Date().toLocaleString(),read:false});saveData(d);addAudit('Website lead created',lead.id);f.reset();toast('Enquiry submitted for admin review.')}}
function memberSession(){return sessionStorage.getItem('gldcMemberId')}
function memberPage(){const d=getData(),mid=memberSession(),m=d.members.find(x=>x.id===mid);if(!m){shell(pageHero('member','MEMBER AREA')+`<section class="section"><div class="container grid grid-2"><form id="memberLogin" class="card"><h2>Member sign in</h2><p>Demo account or create a new member account.</p><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Password</label><input name="password" type="password" required></div><button class="btn primary">SIGN IN</button><p class="kicker" style="margin-top:12px">New member? <button type="button" class="link-btn" id="showMemberSignup">Create account</button></p></form><form id="memberSignup" class="card" style="display:none"><h2>Become a member</h2><div class="field"><label>Full name</label><input name="name" required></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Phone</label><input name="phone" required></div><div class="field"><label>Password</label><input name="password" type="password" minlength="6" required></div><button class="btn primary">CREATE MEMBER ACCOUNT</button></form></div></div></section>`);bindMemberAuth();return}memberDashboard(m)}
function bindMemberAuth(){const l=document.getElementById('memberLogin'),s=document.getElementById('memberSignup');document.getElementById('showMemberSignup').onclick=()=>{l.style.display='none';s.style.display='block'};l.onsubmit=e=>{e.preventDefault();const fd=new FormData(l),d=getData(),m=d.members.find(x=>x.email.toLowerCase()===String(fd.get('email')).toLowerCase()&&x.password===fd.get('password'));if(!m){toast('Member account not found or password is incorrect.');return}sessionStorage.setItem('gldcMemberId',m.id);location.reload()};s.onsubmit=e=>{e.preventDefault();const fd=new FormData(s),d=getData();if(d.members.some(x=>x.email.toLowerCase()===String(fd.get('email')).toLowerCase())){toast('An account with that email already exists.');return}const m={id:uid('MEM'),name:fd.get('name'),email:fd.get('email'),phone:fd.get('phone'),password:fd.get('password'),status:'ACTIVE',created:new Date().toISOString().slice(0,10)};d.members.unshift(m);d.notifications.unshift({id:uid('NOT'),type:'NEW MEMBER',channel:'IN-APP',message:`New member account created: ${m.name}`,time:new Date().toLocaleString(),read:false});saveData(d);sessionStorage.setItem('gldcMemberId',m.id);addAudit('Member account created',m.id);location.reload()}}
function memberDashboard(m){const d=getData(),leads=d.leads.filter(x=>x.memberId===m.id),payments=d.payments.filter(x=>x.memberId===m.id);shell(`<section class="page-hero"><div class="container"><span class="eyebrow">MEMBER DASHBOARD</span><h1>Welcome, ${esc(m.name)}</h1><p>${esc(d.content['member.hero.body'])}</p></div></section><section class="section"><div class="container"><div class="member-toolbar"><div><span class="tag">ACCOUNT ACTIVE</span><p>${esc(m.email)} · ${esc(m.phone)}</p></div><div class="hero-actions"><button class="btn primary" id="newMemberLead">CREATE PROJECT LEAD</button><button class="btn secondary" id="logoutMember">LOG OUT</button></div></div><div class="grid grid-2" style="margin-top:22px"><div class="panel"><h3>My leads</h3>${leads.map((l,i)=>`<div class="list-row"><div><strong>${esc(l.name)}</strong><p>${esc(l.service)} · ${esc(l.location)}</p></div><div>${statusPill(l.status)} ${l.status==='APPROVED'?`<button class="btn small primary" data-member-pay="${esc(l.id)}">PAY DEPOSIT</button>`:''}</div></div>`).join('')||'<div class="notice">No project leads yet.</div>'}</div><div class="panel"><h3>My payments</h3>${payments.map(p=>`<div class="list-row"><div><strong>${esc(p.reference||p.id)}</strong><p>${esc(p.method)} · ${esc(p.date)}</p></div><div>${money(p.amount)} ${statusPill(p.status)}</div></div>`).join('')||'<div class="notice">No member payments recorded.</div>'}</div></div></div></section>`);document.getElementById('logoutMember').onclick=()=>{sessionStorage.removeItem('gldcMemberId');location.reload()};document.getElementById('newMemberLead').onclick=()=>showMemberLeadForm(m.id);document.querySelectorAll('[data-member-pay]').forEach(b=>b.onclick=()=>memberPaymentPrompt(b.dataset.memberPay))}
function showMemberLeadForm(mid){const d=getData();const m=d.members.find(x=>x.id===mid),mEl=modal('Create Project Lead',`<form id="memberLeadForm" class="form-grid"><div class="field"><label>Project name</label><input name="name" required></div><div class="field"><label>Location</label><input name="location" required></div><div class="field full"><label>Service</label><select name="service">${d.services.filter(s=>s.published).map(s=>`<option>${esc(s.name)}</option>`).join('')}</select></div><div class="field full"><label>Project details</label><textarea name="message" required></textarea></div><div class="field full"><label>Requested project price / estimated value (KES)</label><input name="value" type="number" min="0" required></div><div class="field full"><button class="btn primary">SUBMIT LEAD FOR ADMIN APPROVAL</button></div></form>`);mEl.querySelector('form').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),d2=getData(),lead={id:'GLDC-LEAD-'+String(d2.leads.length+1).padStart(4,'0'),source:'MEMBER',memberId:mid,name:fd.get('name'),email:m.email,phone:m.phone,location:fd.get('location'),service:fd.get('service'),message:fd.get('message'),requestedValue:Number(fd.get('value')),status:'MEMBER_SUBMITTED',priority:'High',created:new Date().toISOString().slice(0,10)};d2.leads.unshift(lead);d2.notifications.unshift({id:uid('NOT'),type:'MEMBER LEAD',channel:'IN-APP',message:`Member ${m.name} submitted ${lead.id} for approval.`,time:new Date().toLocaleString(),read:false});saveData(d2);addAudit('Member lead submitted',lead.id);mEl.remove();toast('Lead submitted. Admin approval is required before payment processing.');location.reload()}}
function memberPaymentPrompt(leadId){const d=getData(),lead=d.leads.find(x=>x.id===leadId);if(!lead||lead.status!=='APPROVED'){toast('Payment is locked until the lead is approved by GLDC.');return}const amount=Number(lead.depositRequired||lead.requestedValue*0.2||0);const mEl=modal('M-Pesa Deposit Prompt',`<div class="notice"><strong>Demo STK prompt</strong><br>Recipient: GLDC<br>Amount: ${money(amount)}<br>Phone: ${esc(lead.phone)}</div><p>A real integration would send an M-Pesa STK push and wait for a verified gateway callback.</p><div class="hero-actions"><button class="btn primary" id="simulateMpesa">SIMULATE M-PESA SUCCESS</button><button class="btn secondary" id="cancelPay">CANCEL</button></div>`);mEl.querySelector('#cancelPay').onclick=()=>mEl.remove();mEl.querySelector('#simulateMpesa').onclick=()=>{const d2=getData(),id=uid('PAY'),ref='MPESA-DEMO-'+Math.random().toString(36).slice(2,8).toUpperCase();d2.payments.unshift({id,invoice:'',leadId,memberId:lead.memberId,amount,method:'M-Pesa STK Prompt',status:'SUCCESSFUL',date:new Date().toISOString().slice(0,10),reference:ref});d2.notifications.unshift({id:uid('NOT'),type:'PAYMENT RECEIVED',channel:'IN-APP',message:`M-Pesa deposit ${ref} recorded for ${lead.id}.`,time:new Date().toLocaleString(),read:false});saveData(d2);addAudit('Member M-Pesa payment simulated',id);mEl.remove();toast('Demo M-Pesa payment successful and recorded in admin.');location.reload()}}
function verifyPage(){const d=getData(),doc=new URLSearchParams(location.search).get('doc'),mid=memberSession();if(!mid){shell(`<section class="page-hero"><div class="container"><span class="eyebrow">SECURE VERIFICATION</span><h1>Member access required</h1><p>The QR verification endpoint is restricted to authenticated GLDC members.</p></div></section><section class="section"><div class="container"><div class="card"><a class="btn primary" href="member.html">SIGN IN / BECOME A MEMBER</a></div></div></section>`);return}const x=d.documents.find(z=>z.id===doc);shell(`<section class="page-hero"><div class="container"><span class="eyebrow">DOCUMENT VERIFICATION</span><h1>${x?esc(x.name):'Document not found'}</h1><p>Authenticated member verification result.</p></div></section><section class="section"><div class="container"><div class="card"><span class="tag">VERIFIED RECORD</span><h2>${x?esc(x.name):'Invalid document'}</h2><p>Document ID: ${esc(doc||'')}</p><p>Issued / generated by GLDC: ${esc(x?.date||'')}</p><p>Access: ${esc(x?.access||'PRIVATE')}</p><div class="notice">This is a prototype verification record. Production verification should use a server-side signed document registry.</div></div></div></section>`)}
function documentPage(){const d=getData(),id=new URLSearchParams(location.search).get('id')||d.projects[0]?.id,p=d.projects.find(x=>x.id===id);let record=d.documents.find(x=>x.project===id);if(!record){const newDocId=uid('DOC');record={id:newDocId,name:`${p?.name||'Project'} Proof of Work`,project:id,access:'MEMBER-ONLY',status:'PREVIEW',date:new Date().toISOString().slice(0,10),verify:`verify.html?doc=${encodeURIComponent(newDocId)}`}}const verifyUrl=new URL(record.verify,location.href).href;const qr=`https://api.qrserver.com/v1/create-qr-code/?size=180x180&data=${encodeURIComponent(verifyUrl)}`;shell(`<section class="page-hero"><div class="container"><span class="eyebrow">PROJECT DOCUMENT</span><h1>Project proof-of-work document</h1><p>Admin-designed print view with QR verification, signature and office stamp areas.</p></div></section><section class="section"><div class="container"><div class="card print-doc" id="projectDoc"><div class="doc-head"><img src="assets/gldc-logo.png" alt="GLDC logo"><div><strong>GLDC PROJECT DOCUMENT</strong><div class="kicker">${esc(record.date)}</div></div></div><hr class="sep"><h2>${esc(p?.name||'Project')}</h2><p>${esc(p?.description||'Project proof-of-work record.')}</p><p><strong>Project ID:</strong> ${esc(p?.id||'')}</p><p><strong>Value:</strong> ${money(p?.value)}</p><p><strong>Document ID:</strong> ${esc(record.id)}</p><div class="signature-grid"><div><div class="signature-line"></div><small>ADMIN SIGNATURE</small></div><div><div class="signature-line"></div><small>OFFICE STAMP / SEAL</small></div><div id="qrBox"><img class="qr-image" src="${esc(qr)}" alt="QR verification code"><small>SCAN TO VERIFY<br>MEMBER LOGIN REQUIRED</small></div></div></div><div class="hero-actions" style="margin-top:18px"><button class="btn primary" id="genPdf">GENERATE / PRINT PDF</button>${record.status==='PREVIEW'?`<button class="btn secondary" id="saveDocRecord">SAVE DOCUMENT RECORD</button>`:''}<a class="btn ghost" href="${esc(record.verify)}">OPEN VERIFICATION PAGE</a></div></div></section>`);document.getElementById('genPdf').onclick=()=>window.print();const save=document.getElementById('saveDocRecord');if(save)save.onclick=()=>{const d2=getData();d2.documents.unshift({...record,status:'ACTIVE'});saveData(d2);addAudit('Project PDF document record created',record.id);toast('Document record saved with QR verification. Refresh to use the permanent record.')}}
function customFormPage(){const d=getData(),id=new URLSearchParams(location.search).get('id')||d.forms[0]?.id,f=d.forms.find(x=>x.id===id);if(!f){shell(pageHero('quote','FORM')+'<section class="section"><div class="container"><div class="notice">Form not found.</div></div></section>');return}shell(`<section class="page-hero"><div class="container"><span class="eyebrow">CUSTOM FORM</span><h1>${esc(f.name)}</h1><p>Form fields are configurable by the administrator.</p></div></section><section class="section"><div class="container"><form id="customForm" class="card form-grid">${f.fields.map(fieldHtml).join('')}<div class="field full"><button class="btn primary">SUBMIT FORM</button></div></form></div></section>`);document.getElementById('customForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),vals={};f.fields.forEach(x=>vals[x.name]=fd.get(x.name));const d2=getData();d2.formSubmissions.unshift({id:uid('SUB'),formId:f.id,values:vals,date:new Date().toISOString()});d2.notifications.unshift({id:uid('NOT'),type:'FORM SUBMISSION',channel:'IN-APP',message:`New ${f.name} submission.`,time:new Date().toLocaleString(),read:false});saveData(d2);addAudit('Custom form submitted',f.id);e.target.reset();toast('Form submitted for review.')}}
function fieldHtml(x){let input='';if(x.type==='textarea')input=`<textarea name="${esc(x.name)}" rows="5" ${x.required?'required':''}></textarea>`;else if(x.type==='select')input=`<select name="${esc(x.name)}" ${x.required?'required':''}>${(x.options||[]).map(o=>`<option>${esc(o)}</option>`).join('')}</select>`;else if(x.type==='checkbox')input=`<label class="check"><input type="checkbox" name="${esc(x.name)}" value="Yes" ${x.required?'required':''}> ${esc(x.label)}</label>`;else if(x.type==='radio')input=(x.options||['Yes','No']).map(o=>`<label class="check"><input type="radio" name="${esc(x.name)}" value="${esc(o)}" ${x.required?'required':''}> ${esc(o)}</label>`).join('');else input=`<input type="${['text','email','number','date','url','tel'].includes(x.type)?x.type:'text'}" name="${esc(x.name)}" ${x.required?'required':''}>`;return `<div class="field ${x.type==='textarea'?'full':''}"><label>${esc(x.label)}${x.required?' *':''}</label>${input}</div>`}
function modal(title,html){let m=document.getElementById('appModal');if(!m){m=document.createElement('div');m.id='appModal';m.className='modal';document.body.appendChild(m)}m.innerHTML=`<div class="modal-box"><div class="modal-head"><h3>${esc(title)}</h3><button class="close" type="button">✕</button></div>${html}</div>`;m.classList.add('open');m.querySelector('.close').onclick=()=>m.remove();return m}
const ADMIN_MODULES=[['OVERVIEW','Dashboard','▦'],['CRM','Leads','◉'],['CRM','Clients','♟'],['OPERATIONS','Projects','▣'],['OPERATIONS','Tasks','✓'],['OPERATIONS','Consultations','◷'],['FINANCE','Quotations','◒'],['FINANCE','Invoices','▤'],['FINANCE','Payments','KSh'],['WEBSITE','Pages & Sections','✎'],['WEBSITE','Services','◆'],['WEBSITE','Portfolio','▰'],['WEBSITE','Team Approval','●'],['WEBSITE','Testimonials','★'],['WEBSITE','Media','▤'],['WEBSITE','Custom Forms','⌘'],['MEMBERS','Members','♙'],['COMMUNICATION','Notifications','●'],['COMMUNICATION','Email Center','✉'],['DOCUMENTS','Documents & PDFs','▧'],['SYSTEM','Users & Roles','♜'],['SYSTEM','Audit Logs','☷'],['SYSTEM','Brand Settings','◈'],['SYSTEM','System Settings','⚙']];
function adminLogin(){const s=document.getElementById('loginScreen'),sh=document.getElementById('adminShell');if(sessionStorage.getItem('gldcAdminDemo')==='1'){s.style.display='none';sh.style.display='grid';renderAdmin();return}s.style.display='grid';document.getElementById('loginForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);if(f.get('email')==='admin@gldc.local'&&f.get('password')==='GLDC-DEMO-2026'){sessionStorage.setItem('gldcAdminDemo','1');s.style.display='none';sh.style.display='grid';renderAdmin()}else toast('Invalid demo credentials.')}}
function adminSidebar(){let current=location.hash.replace('#','')||'Dashboard';let last='';return `<div class="admin-brand"><img src="assets/gldc-logo.png" alt="GLDC"></div><nav class="admin-nav">${ADMIN_MODULES.map(x=>{const [g,n,ic]=x;let h='';if(g!==last){last=g;h+=`<div class="group-title">${g}</div>`}h+=`<button class="${current===n?'active':''}" data-admin-module="${esc(n)}"><span>${ic}</span>${esc(n)}</button>`;return h}).join('')}</nav>`}
function adminLayout(){const sh=document.getElementById('adminShell');sh.innerHTML=`<aside class="admin-sidebar">${adminSidebar()}</aside><main class="admin-main"><header class="admin-top"><div><strong>GLDC MANAGEMENT CONSOLE</strong><div class="kicker">Full prototype · CMS · approvals · members · finance · documents</div></div><div class="top-actions"><span class="tag" id="notifCount"></span><a class="btn small secondary" href="index.html">VIEW WEBSITE</a><button class="btn small ghost" id="adminLogout">LOG OUT</button></div></header><div class="admin-mobile-nav"><select id="adminModuleSelect">${ADMIN_MODULES.map(x=>`<option>${esc(x[1])}</option>`).join('')}</select></div><div class="admin-content" id="adminContent"></div></main>`;document.querySelectorAll('[data-admin-module]').forEach(b=>b.onclick=()=>switchAdminModule(b.dataset.adminModule));document.getElementById('adminLogout').onclick=()=>{sessionStorage.removeItem('gldcAdminDemo');location.reload()};document.getElementById('adminModuleSelect').onchange=e=>switchAdminModule(e.target.value)}
function switchAdminModule(name){location.hash=encodeURIComponent(name);document.querySelectorAll('[data-admin-module]').forEach(b=>b.classList.toggle('active',b.dataset.adminModule===name));const sel=document.getElementById('adminModuleSelect');if(sel)sel.value=name;document.getElementById('adminContent').innerHTML=adminView(name);bindAdmin();const d=getData();const c=d.notifications.filter(n=>!n.read).length;const nc=document.getElementById('notifCount');if(nc)nc.textContent=c?`${c} NEW NOTIFICATIONS`:'NO NEW NOTIFICATIONS'}
function title(t,sub,actions=''){return `<div class="admin-title"><div><h2>${esc(t)}</h2><p>${esc(sub)}</p></div><div class="hero-actions">${actions}</div></div>`}
function adminView(n){const d=getData();if(n==='Dashboard')return dashboardView(d);if(n==='Leads')return leadsAdmin(d);if(n==='Clients')return clientsAdmin(d);if(n==='Projects')return projectsAdmin(d);if(n==='Tasks')return tableAdmin('Tasks','Manage project tasks and deadlines',d.tasks,['id','title','project','assigned','status','due'],()=>showTaskForm());if(n==='Consultations')return tableAdmin('Consultations','Consultation calendar and status',d.calendar,['id','client','date','time','status'],()=>showConsultationForm());if(n==='Quotations')return financeAdmin('Quotations',d.quotes,['id','client','project','total','status','date'],()=>showQuoteForm());if(n==='Invoices')return invoiceAdmin(d);if(n==='Payments')return paymentsAdmin(d);if(n==='Pages & Sections')return pagesAdmin(d);if(n==='Services')return servicesAdmin(d);if(n==='Portfolio')return portfolioAdmin(d);if(n==='Team Approval')return teamAdmin(d);if(n==='Testimonials')return testimonialAdmin(d);if(n==='Media')return mediaAdmin(d);if(n==='Custom Forms')return formsAdmin(d);if(n==='Members')return membersAdmin(d);if(n==='Notifications')return notificationsAdmin(d);if(n==='Email Center')return emailAdmin(d);if(n==='Documents & PDFs')return docsAdmin(d);if(n==='Users & Roles')return usersAdmin(d);if(n==='Audit Logs')return auditAdmin(d);if(n==='Brand Settings')return settingsAdmin(d,true);if(n==='System Settings')return settingsAdmin(d,false);return dashboardView(d)}
function dashboardView(d){const revenue=d.payments.filter(p=>p.status==='SUCCESSFUL').reduce((a,p)=>a+Number(p.amount),0);return title('Dashboard','Operational overview with approval gates and finance controls',`<button class="btn primary small" data-admin-action="new-lead">+ NEW LEAD</button>`)+`<div class="kpi-grid"><div class="kpi"><div class="label">Pending lead approvals</div><div class="value">${d.leads.filter(x=>['MEMBER_SUBMITTED','NEW'].includes(x.status)).length}</div></div><div class="kpi"><div class="label">Approved projects</div><div class="value">${d.projects.filter(x=>x.approved).length}</div></div><div class="kpi"><div class="label">Members</div><div class="value">${d.members.length}</div></div><div class="kpi"><div class="label">Recorded revenue</div><div class="value">${money(revenue)}</div></div></div><div class="admin-grid" style="margin-top:18px"><div class="panel"><div class="panel-head"><h3>Approval queue</h3><span class="tag">ADMIN ACTION REQUIRED</span></div>${d.leads.filter(x=>['MEMBER_SUBMITTED','NEW'].includes(x.status)).slice(0,8).map((l,i)=>`<div class="list-row"><div><strong>${esc(l.id)}</strong><p>${esc(l.name)} · ${esc(l.service)}</p></div><div>${statusPill(l.status)} <button class="btn small primary" data-lead-approve="${d.leads.indexOf(l)}">APPROVE</button></div></div>`).join('')||'<div class="notice">Queue clear.</div>'}</div><div class="panel"><div class="panel-head"><h3>Quick actions</h3></div><div class="quick-grid">${['Pages & Sections','Team Approval','Custom Forms','Members','Payments','Documents & PDFs'].map(x=>`<button class="btn secondary" data-jump="${x}">${x}</button>`).join('')}</div></div></div>`}
function tableAdmin(name,sub,arr,cols,add){const act={'Tasks':'new-task','Consultations':'new-consultation'}[name]||'';return title(name,sub,`<button class="btn primary small" data-admin-action="${act}">+ ADD</button>`)+`<div class="panel table-wrap"><table class="table"><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}</tr></thead><tbody>${arr.map(x=>`<tr>${cols.map(c=>`<td>${c==='total'||c==='amount'?money(x[c]):c==='status'?statusPill(x[c]):esc(x[c])}</td>`).join('')}</tr>`).join('')||'<tr><td colspan="8">No records.</td></tr>'}</tbody></table></div>`}
function leadsAdmin(d){return title('CRM / Leads','All website and member leads. Member-submitted leads are blocked from payment until approved.',`<button class="btn primary small" data-admin-action="new-lead">+ ADD LEAD</button>`)+`<div class="panel table-wrap"><table class="table"><thead><tr><th>ID</th><th>Lead</th><th>Source</th><th>Service</th><th>Status</th><th>Requested value</th><th>Actions</th></tr></thead><tbody>${d.leads.map((l,i)=>`<tr><td>${esc(l.id)}</td><td><strong>${esc(l.name)}</strong><div class="muted">${esc(l.email)}</div></td><td>${esc(l.source)}</td><td>${esc(l.service)}</td><td>${statusPill(l.status)}</td><td>${money(l.requestedValue)}</td><td><button class="btn small ghost" data-lead-edit="${i}">EDIT</button> <button class="btn small primary" data-lead-approve="${i}">APPROVE</button> <button class="btn small secondary" data-lead-reject="${i}">REJECT</button></td></tr>`).join('')}</tbody></table></div>`}
function clientsAdmin(d){return title('Clients','Client records and project relationships',`<button class="btn primary small" data-admin-action="new-client">+ ADD CLIENT</button>`)+`<div class="panel table-wrap"><table class="table"><thead><tr><th>ID</th><th>Name</th><th>Company</th><th>Contact</th><th>Projects</th><th>Status</th></tr></thead><tbody>${d.clients.map(c=>`<tr><td>${esc(c.id)}</td><td>${esc(c.name)}</td><td>${esc(c.company)}</td><td>${esc(c.email)}<br>${esc(c.phone)}</td><td>${d.projects.filter(p=>p.client===c.name).length}</td><td>${statusPill(c.status)}</td></tr>`).join('')}</tbody></table></div>`}
function projectsAdmin(d){return title('Projects','Project lifecycle, prices, deposits and publication approval',`<button class="btn primary small" data-admin-action="new-project">+ ADD PROJECT</button>`)+`<div class="grid grid-2">${d.projects.map((p,i)=>`<article class="card"><div style="display:flex;justify-content:space-between;gap:10px"><span class="tag">${esc(p.id)}</span>${statusPill(p.status)}</div><h3>${esc(p.name)}</h3><p>${esc(p.client)} · ${money(p.value)}</p><p>Deposit: <strong>${money(p.depositRequired)}</strong></p><p>Public: ${statusPill(p.published?'PUBLISHED':'DRAFT')} · Approval: ${statusPill(p.approved?'APPROVED':'PENDING')}</p><div class="hero-actions"><button class="btn small ghost" data-project-edit="${i}">EDIT</button><button class="btn small secondary" data-project-publish="${i}">${p.published?'UNPUBLISH':'PUBLISH'}</button><button class="btn small primary" data-project-pdf="${i}">PROJECT PDF</button></div></article>`).join('')}</div>`}
function financeAdmin(name,arr,cols){return title(name,'Quotes, proposals and status control',`<button class="btn primary small" data-admin-action="new-quote">+ ADD QUOTE</button>`)+`<div class="panel table-wrap"><table class="table"><thead><tr>${cols.map(c=>`<th>${esc(c)}</th>`).join('')}<th>Action</th></tr></thead><tbody>${arr.map((x,i)=>`<tr>${cols.map(c=>`<td>${c==='total'?money(x[c]):c==='status'?statusPill(x[c]):esc(x[c])}</td>`).join('')}<td><button class="btn small secondary" data-quote-send="${i}">MARK SENT</button></td></tr>`).join('')}</tbody></table></div>`}
function invoiceAdmin(d){return title('Invoices','Issue invoices and track balances',`<button class="btn primary small" data-admin-action="new-invoice">+ CREATE INVOICE</button>`)+`<div class="panel table-wrap"><table class="table"><thead><tr><th>ID</th><th>Client</th><th>Project</th><th>Total</th><th>Paid</th><th>Balance</th><th>Status</th></tr></thead><tbody>${d.invoices.map(x=>`<tr><td>${esc(x.id)}</td><td>${esc(x.client)}</td><td>${esc(x.project)}</td><td>${money(x.total)}</td><td>${money(x.paid)}</td><td>${money(x.total-x.paid)}</td><td>${statusPill(x.status)}</td></tr>`).join('')}</tbody></table></div>`}
function paymentsAdmin(d){return title('Payments','M-Pesa and other payment records. Demo prompts are recorded here after simulation.',`<button class="btn primary small" data-admin-action="new-payment">+ RECORD PAYMENT</button>`)+`<div class="notice" style="margin-bottom:18px"><strong>Payment gate:</strong> member payments can only be initiated after a lead reaches APPROVED. This static prototype simulates the M-Pesa prompt; production should verify gateway callbacks.</div><div class="panel table-wrap"><table class="table"><thead><tr><th>ID</th><th>Lead / Invoice</th><th>Member</th><th>Amount</th><th>Method</th><th>Reference</th><th>Status</th></tr></thead><tbody>${d.payments.map(x=>`<tr><td>${esc(x.id)}</td><td>${esc(x.leadId||x.invoice||'—')}</td><td>${esc(x.memberId||'—')}</td><td>${money(x.amount)}</td><td>${esc(x.method)}</td><td>${esc(x.reference||'—')}</td><td>${statusPill(x.status)}</td></tr>`).join('')}</tbody></table></div>`}
function pagesAdmin(d){return title('Pages & Sections','Edit every named website field. DEFAULT marks starter text; custom sections can be added without code.',`<button class="btn primary small" data-admin-action="new-content">+ ADD CONTENT FIELD</button> <button class="btn secondary small" data-admin-action="new-section">+ ADD SECTION</button>`)+`<div class="panel"><div class="content-editor">${Object.entries(d.content).map(([k,v])=>`<div class="content-row"><div class="key">${esc(k)}<br><span class="badge-default">DEFAULT</span></div><input data-content-key="${esc(k)}" value="${esc(v)}"><button class="btn small ghost" data-content-delete="${esc(k)}">DELETE</button></div>`).join('')}</div><div class="hero-actions" style="margin-top:18px"><button class="btn primary" data-admin-action="save-content">SAVE ALL CONTENT</button></div></div><div class="panel" style="margin-top:18px"><div class="panel-head"><h3>Custom published sections</h3><span class="kicker">Responsive image + text blocks</span></div>${d.sections.map((s,i)=>`<div class="list-row"><div><strong>${esc(s.title)}</strong><p>${esc(s.page)} · ${esc(s.variant||'standard')}</p></div><div>${statusPill(s.published?'PUBLISHED':'DRAFT')} <button class="btn small ghost" data-section-edit="${i}">EDIT</button> <button class="btn small secondary" data-section-toggle="${i}">${s.published?'UNPUBLISH':'PUBLISH'}</button></div></div>`).join('')||'<div class="notice">No custom sections yet.</div>'}</div>`}
function servicesAdmin(d){return title('Services CMS','Add, edit and publish responsive service cards.',`<button class="btn primary small" data-admin-action="new-service">+ ADD SERVICE</button>`)+`<div class="grid grid-2">${d.services.map((s,i)=>`<article class="card"><img class="project-img" src="${esc(s.image||DEFAULT_IMAGES.land)}" alt="${esc(s.name)}"><span class="badge-default">${s.published?'PUBLISHED':'DRAFT'}</span><h3>${esc(s.name)}</h3><p>${esc(s.category)}</p><p>${esc(s.description)}</p><div class="hero-actions"><button class="btn small ghost" data-service-edit="${i}">EDIT</button><button class="btn small ${s.published?'secondary':'primary'}" data-service-toggle="${i}">${s.published?'UNPUBLISH':'PUBLISH'}</button></div></article>`).join('')}</div>`}
function portfolioAdmin(d){return title('Portfolio CMS','Projects require administrative approval before public publication.',`<button class="btn primary small" data-admin-action="new-project">+ ADD PROJECT</button>`)+`<div class="grid grid-3">${d.projects.map((p,i)=>`<article class="card"><img class="project-img" src="${esc((p.images||[])[0]||DEFAULT_IMAGES.building)}" alt="${esc(p.name)}"><span class="tag">${esc(p.id)}</span><h3>${esc(p.name)}</h3><p>${money(p.value)} · Deposit ${money(p.depositRequired)}</p><p>${statusPill(p.approved?'APPROVED':'PENDING')} ${statusPill(p.published?'PUBLISHED':'DRAFT')}</p><button class="btn small ghost" data-project-edit="${i}">EDIT</button> <button class="btn small primary" data-project-publish="${i}">${p.published?'UNPUBLISH':'PUBLISH'}</button></article>`).join('')}</div>`}
function teamAdmin(d){return title('Team Approval','Create profiles, edit details and publish only after approval.',`<button class="btn primary small" data-admin-action="new-team">+ ADD TEAM PROFILE</button>`)+`<div class="grid grid-2">${d.team.map((t,i)=>`<article class="card"><div style="display:flex;gap:16px;align-items:center"><img class="avatar" src="${esc(t.photo||DEFAULT_IMAGES.team)}" alt="${esc(t.name)}"><div><span class="tag">${esc(t.status||'DRAFT')}</span><h3>${esc(t.name)}</h3><p>${esc(t.position)}</p></div></div><hr class="sep"><p><strong>Qualification:</strong> ${esc(t.qualification)}</p><p>${esc(t.bio)}</p><div class="hero-actions"><button class="btn small ghost" data-team-edit="${i}">EDIT</button><button class="btn small primary" data-team-approve="${i}">${t.status==='APPROVED'?'UNAPPROVE':'APPROVE & PUBLISH'}</button></div></article>`).join('')}</div>`}
function testimonialAdmin(d){return title('Testimonials','Review and approve genuine client testimonials.',`<button class="btn primary small" data-admin-action="new-testimonial">+ ADD TESTIMONIAL</button>`)+`<div class="grid grid-2">${d.testimonials.map((t,i)=>`<article class="card"><span class="tag">${esc(t.status||'DRAFT')}</span><h3>${esc(t.name)}</h3><p>“${esc(t.text)}”</p><p class="kicker">${esc(t.project)}</p><button class="btn small ghost" data-test-edit="${i}">EDIT</button> <button class="btn small primary" data-test-approve="${i}">${t.status==='APPROVED'?'UNPUBLISH':'APPROVE & PUBLISH'}</button></article>`).join('')}</div>`}
function mediaAdmin(d){return title('Media Library','Use online placeholder URLs or approved image URLs. All images use responsive containers.',`<button class="btn primary small" data-admin-action="new-media">+ ADD IMAGE</button>`)+`<div class="grid grid-3">${d.media.map((m,i)=>`<article class="card"><img class="project-img" src="${esc(m.url)}" alt="${esc(m.alt||m.name)}"><h3>${esc(m.name)}</h3><p>${esc(m.type)} · ${m.approved?'APPROVED':'DRAFT'}</p><button class="btn small ghost" data-media-edit="${i}">EDIT</button></article>`).join('')}</div><div class="panel" style="margin-top:18px"><strong>Image format rules</strong><p class="kicker">Use HTTPS image URLs, descriptive ALT text, and landscape/portrait originals. The frontend applies object-fit, max-width:100%, lazy-friendly responsive sizing, and consistent aspect ratios.</p></div>`}
function formsAdmin(d){return title('Custom Forms','Build forms with different data types and publish them at a generated page.',`<button class="btn primary small" data-admin-action="new-form">+ CREATE FORM</button>`)+`<div class="grid grid-2">${d.forms.map((f,i)=>`<article class="card"><span class="tag">${f.published?'PUBLISHED':'DRAFT'}</span><h3>${esc(f.name)}</h3><p>${f.fields.length} fields · ${esc(f.slug)}</p><div class="chips">${f.fields.map(x=>`<span class="tag">${esc(x.type)}</span>`).join('')}</div><div class="hero-actions"><a class="btn small secondary" href="form.html?id=${encodeURIComponent(f.id)}">OPEN FORM</a><button class="btn small ghost" data-form-edit="${i}">EDIT</button><button class="btn small primary" data-form-toggle="${i}">${f.published?'UNPUBLISH':'PUBLISH'}</button></div></article>`).join('')}</div><div class="panel" style="margin-top:18px"><h3>Supported data types</h3><p>text, email, tel, number, date, url, textarea, select, radio, checkbox.</p></div>`}
function membersAdmin(d){return title('Members','Member accounts and their submitted leads.',`<button class="btn primary small" data-admin-action="new-member">+ ADD MEMBER</button>`)+`<div class="panel table-wrap"><table class="table"><thead><tr><th>ID</th><th>Member</th><th>Contact</th><th>Leads</th><th>Payments</th><th>Status</th></tr></thead><tbody>${d.members.map(m=>`<tr><td>${esc(m.id)}</td><td><strong>${esc(m.name)}</strong></td><td>${esc(m.email)}<br>${esc(m.phone)}</td><td>${d.leads.filter(l=>l.memberId===m.id).length}</td><td>${money(d.payments.filter(p=>p.memberId===m.id).reduce((a,p)=>a+Number(p.amount),0))}</td><td>${statusPill(m.status)}</td></tr>`).join('')||'<tr><td colspan="6">No members yet.</td></tr>'}</tbody></table></div>`}
function notificationsAdmin(d){return title('Notification Center','Create, read and trigger operational notifications.',`<button class="btn primary small" data-admin-action="new-notification">+ CREATE NOTIFICATION</button> <button class="btn secondary small" data-admin-action="mark-read">MARK ALL READ</button>`)+`<div class="panel table-wrap"><table class="table"><thead><tr><th>Type</th><th>Channel</th><th>Message</th><th>Time</th><th>State</th></tr></thead><tbody>${d.notifications.map((n,i)=>`<tr><td>${esc(n.type)}</td><td>${esc(n.channel)}</td><td>${esc(n.message)}</td><td>${esc(n.time)}</td><td><button class="btn small ${n.read?'secondary':'primary'}" data-notif-read="${i}">${n.read?'READ':'MARK READ'}</button></td></tr>`).join('')}</tbody></table></div>`}
function emailAdmin(d){return title('Email Center','Editable templates and simulated send actions.',`<button class="btn primary small" data-admin-action="new-email">+ NEW TEMPLATE</button> <button class="btn secondary small" data-admin-action="test-email">SEND TEST</button>`)+`<div class="grid grid-2">${d.emailTemplates.map((t,i)=>`<article class="card"><span class="tag">EMAIL TEMPLATE</span><h3>${esc(t.name)}</h3><p><strong>Subject:</strong> ${esc(t.subject)}</p><div class="code">${esc(t.body)}</div><button class="btn small ghost" data-email-edit="${i}">EDIT</button> <button class="btn small primary" data-email-send="${i}">SIMULATE SEND</button></article>`).join('')}</div><div class="notice" style="margin-top:18px">Production email delivery needs a configured provider/API and server-side secrets. This demo records the action only.</div>`}
function docsAdmin(d){return title('Documents & PDFs','Generate project proof-of-work records with QR verification and signature/stamp areas.',`<button class="btn primary small" data-admin-action="new-document">+ ADD DOCUMENT</button>`)+`<div class="panel table-wrap"><table class="table"><thead><tr><th>ID</th><th>Name</th><th>Project</th><th>Access</th><th>Date</th><th>Actions</th></tr></thead><tbody>${d.documents.map(x=>`<tr><td>${esc(x.id)}</td><td>${esc(x.name)}</td><td>${esc(x.project)}</td><td>${esc(x.access)}</td><td>${esc(x.date)}</td><td><a class="btn small secondary" href="document.html?id=${encodeURIComponent(x.project)}">OPEN / PRINT</a> <a class="btn small ghost" href="${esc(x.verify||'verify.html?doc='+x.id)}">VERIFY</a></td></tr>`).join('')||'<tr><td colspan="6">No document records. Generate one from a project.</td></tr>'}</tbody></table></div><div class="panel" style="margin-top:18px"><strong>QR security:</strong> the QR points to the verification page, which requires a member session in this prototype. Production should use signed server-side tokens and authorization.</div>`}
function usersAdmin(d){return title('Users & Roles','Admin users, roles and access status.',`<button class="btn primary small" data-admin-action="new-user">+ ADD USER</button>`)+`<div class="panel table-wrap"><table class="table"><thead><tr><th>User</th><th>Email</th><th>Role</th><th>Status</th></tr></thead><tbody>${d.users.map(u=>`<tr><td>${esc(u.name)}<div class="muted">${esc(u.id)}</div></td><td>${esc(u.email)}</td><td>${esc(u.role)}</td><td>${statusPill(u.status)}</td></tr>`).join('')}</tbody></table></div>`}
function auditAdmin(d){return title('Audit Logs','Trace important administrative actions and finance events.')+`<div class="panel table-wrap"><table class="table"><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Entity</th><th>Result</th></tr></thead><tbody>${d.audit.map(x=>`<tr><td>${esc(x.time)}</td><td>${esc(x.user)}</td><td>${esc(x.action)}</td><td>${esc(x.entity)}</td><td>${statusPill(x.result)}</td></tr>`).join('')}</tbody></table></div>`}
function settingsAdmin(d,brand){return title(brand?'Brand Settings':'System Settings',brand?'Edit company identity and website contact settings.':'Membership, approvals, security and prototype behavior.')+`<div class="panel"><form id="settingsForm" class="form-grid">${brand?`<div class="field"><label>Company name</label><input name="company" value="${esc(d.settings.company)}"></div><div class="field"><label>Short name</label><input name="shortName" value="${esc(d.settings.shortName)}"></div><div class="field"><label>Tagline</label><input name="tagline" value="${esc(d.settings.tagline)}"></div><div class="field"><label>Phone</label><input name="phone" value="${esc(d.settings.phone)}"></div><div class="field"><label>WhatsApp number</label><input name="whatsapp" value="${esc(d.settings.whatsapp)}"></div><div class="field"><label>Email</label><input name="email" value="${esc(d.settings.email)}"></div><div class="field"><label>Location</label><input name="location" value="${esc(d.settings.location)}"></div><div class="field"><label>Hours</label><input name="hours" value="${esc(d.settings.hours)}"></div>`:`<div class="field"><label>Membership enabled</label><select name="membershipEnabled"><option value="true" ${d.membership.enabled?'selected':''}>ENABLED</option><option value="false" ${!d.membership.enabled?'selected':''}>DISABLED</option></select></div><div class="field"><label>Member button label</label><input name="buttonLabel" value="${esc(d.membership.buttonLabel)}"></div><div class="field"><label>Require admin approval for member leads</label><select name="requiresApproval"><option value="true" ${d.membership.requiresApproval?'selected':''}>YES</option><option value="false" ${!d.membership.requiresApproval?'selected':''}>NO</option></select></div><div class="field full"><div class="notice">Payment gate is always enforced in this prototype: member lead → ADMIN APPROVED → M-Pesa prompt → recorded payment.</div></div>`}<div class="field full"><button class="btn primary">SAVE SETTINGS</button></div></form></div>`}
function showLeadForm(){const m=modal('Add Lead',`<form id="xform" class="form-grid"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Email</label><input name="email" type="email"></div><div class="field"><label>Phone</label><input name="phone"></div><div class="field"><label>Location</label><input name="location"></div><div class="field full"><label>Service</label><input name="service" required></div><div class="field full"><label>Message</label><textarea name="message"></textarea></div><div class="field full"><button class="btn primary">CREATE LEAD</button></div></form>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),d=getData(),id='GLDC-LEAD-'+String(d.leads.length+1).padStart(4,'0');d.leads.unshift({id,source:'ADMIN',memberId:'',name:f.get('name'),email:f.get('email'),phone:f.get('phone'),location:f.get('location'),service:f.get('service'),message:f.get('message'),status:'NEW',priority:'Normal',created:new Date().toISOString().slice(0,10)});saveData(d);addAudit('Admin lead created',id);m.remove();switchAdminModule('Leads');toast('Lead created.')}}
function showClientForm(){const m=modal('Add Client',`<form id="xform" class="form-grid"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Company</label><input name="company"></div><div class="field"><label>Email</label><input name="email" type="email"></div><div class="field"><label>Phone</label><input name="phone"></div><div class="field full"><button class="btn primary">CREATE CLIENT</button></div></form>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),d=getData(),id='GLDC-CLI-'+String(d.clients.length+1).padStart(4,'0');d.clients.unshift({id,name:f.get('name'),company:f.get('company'),email:f.get('email'),phone:f.get('phone'),status:'ACTIVE'});saveData(d);addAudit('Client created',id);m.remove();switchAdminModule('Clients');toast('Client created.')}}
function showProjectForm(i=null){const d=getData(),p=i!==null?d.projects[i]:null,m=modal(p?'Edit Project':'Add Project',`<form id="xform" class="form-grid"><div class="field"><label>Project name</label><input name="name" required value="${esc(p?.name||'')}"></div><div class="field"><label>Client</label><input name="client" value="${esc(p?.client||'')}"></div><div class="field"><label>Value (KES)</label><input name="value" type="number" value="${esc(p?.value||0)}"></div><div class="field"><label>Deposit required (KES)</label><input name="deposit" type="number" value="${esc(p?.depositRequired||0)}"></div><div class="field"><label>Status</label><select name="status">${['PLANNING','DESIGN','APPROVALS','CONSTRUCTION','COMPLETED','ON HOLD'].map(x=>`<option ${p?.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Primary image URL</label><input name="image" value="${esc(p?.images?.[0]||DEFAULT_IMAGES.building)}"></div><div class="field full"><label>Description</label><textarea name="description">${esc(p?.description||'')}</textarea></div><div class="field full"><label>Approved for public use?</label><select name="approved"><option value="true" ${p?.approved?'selected':''}>YES</option><option value="false" ${p&&!p.approved?'selected':''}>NO</option></select></div><div class="field full"><button class="btn primary">SAVE PROJECT</button></div></form>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),d2=getData(),obj={id:p?.id||uid('GLDC-PRJ'),name:f.get('name'),client:f.get('client'),status:f.get('status'),value:Number(f.get('value')),depositRequired:Number(f.get('deposit')),progress:p?.progress||0,published:p?.published||false,approved:f.get('approved')==='true',images:[f.get('image')],description:f.get('description')};if(p)d2.projects[i]=obj;else d2.projects.unshift(obj);saveData(d2);addAudit(p?'Project updated':'Project created',obj.id);m.remove();switchAdminModule('Projects');toast('Project saved.')}}
function showTaskForm(){const m=modal('Add Task',`<form id="xform" class="form-grid"><div class="field full"><label>Title</label><input name="title" required></div><div class="field"><label>Project</label><input name="project"></div><div class="field"><label>Assigned</label><input name="assigned"></div><div class="field"><label>Due</label><input name="due" type="date"></div><div class="field full"><button class="btn primary">CREATE TASK</button></div></form>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),d=getData(),id=uid('TASK');d.tasks.unshift({id,title:f.get('title'),project:f.get('project'),assigned:f.get('assigned'),status:'PENDING',due:f.get('due')});saveData(d);addAudit('Task created',id);m.remove();switchAdminModule('Tasks');toast('Task created.')}}
function showConsultationForm(){const m=modal('Book Consultation',`<form id="xform" class="form-grid"><div class="field"><label>Client</label><input name="client" required></div><div class="field"><label>Date</label><input name="date" type="date" required></div><div class="field"><label>Time</label><input name="time" type="time" required></div><div class="field full"><button class="btn primary">SAVE CONSULTATION</button></div></form>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),d=getData(),id=uid('CONS');d.calendar.unshift({id,client:f.get('client'),date:f.get('date'),time:f.get('time'),status:'BOOKED'});d.notifications.unshift({id:uid('NOT'),type:'CONSULTATION BOOKED',channel:'IN-APP',message:`Consultation booked with ${f.get('client')}.`,time:new Date().toLocaleString(),read:false});saveData(d);addAudit('Consultation booked',id);m.remove();switchAdminModule('Consultations');toast('Consultation saved.')}}
function showQuoteForm(){const d=getData(),m=modal('Create Quotation',`<form id="xform" class="form-grid"><div class="field"><label>Client</label><input name="client" required></div><div class="field"><label>Project ID</label><input name="project"></div><div class="field"><label>Total (KES)</label><input name="total" type="number" required></div><div class="field"><label>Status</label><select name="status"><option>DRAFT</option><option>SENT</option><option>ACCEPTED</option><option>REJECTED</option></select></div><div class="field full"><button class="btn primary">CREATE QUOTE</button></div></form>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),d2=getData(),id='GLDC-Q-2026-'+String(d2.quotes.length+1).padStart(4,'0');d2.quotes.unshift({id,client:f.get('client'),project:f.get('project'),total:Number(f.get('total')),status:f.get('status'),date:new Date().toISOString().slice(0,10)});saveData(d2);addAudit('Quotation created',id);m.remove();switchAdminModule('Quotations');toast('Quotation created.')}}
function showInvoiceForm(){const d=getData(),m=modal('Create Invoice',`<form id="xform" class="form-grid"><div class="field"><label>Client</label><input name="client" required></div><div class="field"><label>Project</label><input name="project"></div><div class="field"><label>Total (KES)</label><input name="total" type="number" required></div><div class="field full"><button class="btn primary">CREATE INVOICE</button></div></form>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),d2=getData(),id='GLDC-INV-2026-'+String(d2.invoices.length+1).padStart(4,'0');d2.invoices.unshift({id,client:f.get('client'),project:f.get('project'),total:Number(f.get('total')),paid:0,status:'ISSUED'});saveData(d2);addAudit('Invoice created',id);m.remove();switchAdminModule('Invoices');toast('Invoice created.')}}
