function showContentField(){const m=modal('Add Editable Content Field',`<form id="xform" class="form-grid"><div class="field"><label>Content key</label><input name="key" placeholder="home.hero.notice" required></div><div class="field"><label>Value</label><input name="value" value="DEFAULT — replace this text"></div><div class="field full"><button class="btn primary">ADD FIELD</button></div></form>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),d=getData();d.content[f.get('key')]=f.get('value');saveData(d);m.remove();switchAdminModule('Pages & Sections');toast('Editable content field added.')}}
function showSectionForm(i=null){const d=getData(),s=i!==null?d.sections[i]:null,m=modal(s?'Edit Section':'Add Section',`<form id="xform" class="form-grid"><div class="field"><label>Page</label><select name="page">${['home','about','services','projects','team','testimonials','areas','contact','quote'].map(x=>`<option ${s?.page===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Eyebrow</label><input name="eyebrow" value="${esc(s?.eyebrow||'DEFAULT')}"></div><div class="field full"><label>Title</label><input name="title" value="${esc(s?.title||'DEFAULT — section title')}" required></div><div class="field full"><label>Body</label><textarea name="body">${esc(s?.body||'DEFAULT — section body')}</textarea></div><div class="field"><label>Image URL</label><input name="image" value="${esc(s?.image||'')}"></div><div class="field"><label>Alt text</label><input name="alt" value="${esc(s?.alt||'GLDC section image')}"></div><div class="field"><label>Layout</label><select name="layout"><option>standard</option><option ${s?.layout==='split'?'selected':''}>split</option></select></div><div class="field"><label>Variant</label><select name="variant"><option>standard</option><option ${s?.variant==='alt'?'selected':''}>alt</option></select></div><div class="field"><label>Button text</label><input name="buttonText" value="${esc(s?.buttonText||'')}"></div><div class="field"><label>Button URL</label><input name="buttonUrl" value="${esc(s?.buttonUrl||'quote.html')}"></div><div class="field full"><button class="btn primary">SAVE SECTION</button></div></form>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),d2=getData(),obj={id:s?.id||uid('SEC'),page:f.get('page'),eyebrow:f.get('eyebrow'),title:f.get('title'),body:f.get('body'),image:f.get('image'),alt:f.get('alt'),layout:f.get('layout'),variant:f.get('variant'),buttonText:f.get('buttonText'),buttonUrl:f.get('buttonUrl'),published:s?.published||false};if(s)d2.sections[i]=obj;else d2.sections.unshift(obj);saveData(d2);addAudit(s?'Section updated':'Section created',obj.id);m.remove();switchAdminModule('Pages & Sections');toast('Section saved as draft.')}}
function showServiceForm(i=null){const d=getData(),s=i!==null?d.services[i]:null,m=modal(s?'Edit Service':'Add Service',`<form id="xform" class="form-grid"><div class="field"><label>Name</label><input name="name" value="${esc(s?.name||'')}" required></div><div class="field"><label>Category</label><input name="category" value="${esc(s?.category||'')}" required></div><div class="field full"><label>Description</label><textarea name="description">${esc(s?.description||'DEFAULT — replace')}</textarea></div><div class="field full"><label>Image URL</label><input name="image" value="${esc(s?.image||DEFAULT_IMAGES.land)}"></div><div class="field full"><button class="btn primary">SAVE SERVICE</button></div></form>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),d2=getData(),obj={id:s?.id||uid('SRV'),name:f.get('name'),category:f.get('category'),description:f.get('description'),image:f.get('image'),published:s?.published||false};if(s)d2.services[i]=obj;else d2.services.unshift(obj);saveData(d2);addAudit(s?'Service updated':'Service created',obj.id);m.remove();switchAdminModule('Services');toast('Service saved.')}}
function showTeamForm(i=null){const d=getData(),t=i!==null?d.team[i]:null,m=modal(t?'Edit Team Profile':'Add Team Profile',`<form id="xform" class="form-grid"><div class="field"><label>Name</label><input name="name" value="${esc(t?.name||'')}" required></div><div class="field"><label>Position</label><input name="position" value="${esc(t?.position||'')}" required></div><div class="field full"><label>Qualification</label><input name="qualification" value="${esc(t?.qualification||'DEFAULT — replace')}"></div><div class="field full"><label>Biography</label><textarea name="bio">${esc(t?.bio||'DEFAULT — replace')}</textarea></div><div class="field full"><label>Photo URL</label><input name="photo" value="${esc(t?.photo||DEFAULT_IMAGES.team)}"></div><div class="field full"><button class="btn primary">SAVE PROFILE</button></div></form>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),d2=getData(),obj={id:t?.id||uid('TEAM'),name:f.get('name'),position:f.get('position'),qualification:f.get('qualification'),bio:f.get('bio'),photo:f.get('photo'),status:t?.status||'PENDING',published:t?.published||false};if(t)d2.team[i]=obj;else d2.team.unshift(obj);saveData(d2);addAudit(t?'Team profile updated':'Team profile created',obj.id);m.remove();switchAdminModule('Team Approval');toast('Team profile saved.')}}
function showTestimonialForm(i=null){const d=getData(),t=i!==null?d.testimonials[i]:null,m=modal('Edit Testimonial',`<form id="xform" class="form-grid"><div class="field"><label>Client name</label><input name="name" value="${esc(t?.name||'')}" required></div><div class="field"><label>Project</label><input name="project" value="${esc(t?.project||'')}"></div><div class="field full"><label>Testimonial</label><textarea name="text" required>${esc(t?.text||'')}</textarea></div><div class="field full"><button class="btn primary">SAVE TESTIMONIAL</button></div></form>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),d2=getData(),obj={id:t?.id||uid('TEST'),name:f.get('name'),project:f.get('project'),text:f.get('text'),status:t?.status||'DRAFT',published:t?.published||false};if(t)d2.testimonials[i]=obj;else d2.testimonials.unshift(obj);saveData(d2);addAudit(t?'Testimonial updated':'Testimonial created',obj.id);m.remove();switchAdminModule('Testimonials');toast('Testimonial saved.')}}
function showMediaForm(i=null){const d=getData(),x=i!==null?d.media[i]:null,m=modal('Media Asset',`<form id="xform" class="form-grid"><div class="field"><label>Name</label><input name="name" value="${esc(x?.name||'New image')}" required></div><div class="field"><label>Image URL</label><input name="url" value="${esc(x?.url||DEFAULT_IMAGES.land)}" required></div><div class="field full"><label>Alt text</label><input name="alt" value="${esc(x?.alt||'GLDC project image')}" required></div><div class="field full"><button class="btn primary">SAVE MEDIA</button></div></form>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),d2=getData(),obj={id:x?.id||uid('MED'),name:f.get('name'),url:f.get('url'),type:'image',alt:f.get('alt'),approved:true};if(x)d2.media[i]=obj;else d2.media.unshift(obj);saveData(d2);addAudit(x?'Media updated':'Media added',obj.id);m.remove();switchAdminModule('Media');toast('Media saved.')}}
function showFormBuilder(i=null){const d=getData(),f=i!==null?d.forms[i]:null,m=modal(f?'Edit Custom Form':'Create Custom Form',`<form id="xform"><div class="form-grid"><div class="field"><label>Form name</label><input name="name" value="${esc(f?.name||'New Form')}" required></div><div class="field"><label>Slug</label><input name="slug" value="${esc(f?.slug||'new-form')}" required></div></div><hr class="sep"><div id="builderFields"></div><button type="button" class="btn secondary" id="addBuilderField">+ ADD FIELD</button><div style="margin-top:18px"><button class="btn primary">SAVE FORM</button></div></form>`);const wrap=m.querySelector('#builderFields');let fields=clone(f?.fields||[]);function render(){wrap.innerHTML=fields.map((x,j)=>`<div class="panel" style="margin:10px 0"><div class="form-grid"><div class="field"><label>Field name</label><input data-f="name" data-i="${j}" value="${esc(x.name)}"></div><div class="field"><label>Label</label><input data-f="label" data-i="${j}" value="${esc(x.label)}"></div><div class="field"><label>Type</label><select data-f="type" data-i="${j}">${['text','email','tel','number','date','url','textarea','select','radio','checkbox'].map(z=>`<option ${x.type===z?'selected':''}>${z}</option>`).join('')}</select></div><div class="field"><label>Required</label><select data-f="required" data-i="${j}"><option value="true" ${x.required?'selected':''}>YES</option><option value="false" ${!x.required?'selected':''}>NO</option></select></div><div class="field full"><label>Options (comma separated for select/radio)</label><input data-f="options" data-i="${j}" value="${esc((x.options||[]).join(', '))}"></div><div class="field full"><button type="button" class="btn small ghost" data-remove-field="${j}">REMOVE FIELD</button></div></div></div>`).join('')||'<div class="notice">Add at least one field.</div>';wrap.querySelectorAll('[data-f]').forEach(el=>el.oninput=()=>{const j=+el.dataset.i,field=el.dataset.f;if(field==='required')fields[j][field]=el.value==='true';else if(field==='options')fields[j][field]=el.value.split(',').map(x=>x.trim()).filter(Boolean);else fields[j][field]=el.value});wrap.querySelectorAll('[data-remove-field]').forEach(el=>el.onclick=()=>{fields.splice(+el.dataset.removeField,1);render()})}m.querySelector('#addBuilderField').onclick=()=>{fields.push({name:'field_'+(fields.length+1),label:'New field',type:'text',required:false,options:[]});render()};render();m.querySelector('form').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),d2=getData(),obj={id:f?.id||uid('FORM'),name:fd.get('name'),slug:fd.get('slug'),published:f?.published||false,fields};if(f)d2.forms[i]=obj;else d2.forms.unshift(obj);saveData(d2);addAudit(f?'Custom form updated':'Custom form created',obj.id);m.remove();switchAdminModule('Custom Forms');toast('Custom form saved.')}}
function showMemberForm(){const m=modal('Add Member',`<form id="xform" class="form-grid"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Phone</label><input name="phone"></div><div class="field"><label>Password</label><input name="password" value="GLDC-MEMBER"></div><div class="field full"><button class="btn primary">CREATE MEMBER</button></div></form>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),d=getData(),m2={id:uid('MEM'),name:f.get('name'),email:f.get('email'),phone:f.get('phone'),password:f.get('password'),status:'ACTIVE',created:new Date().toISOString().slice(0,10)};d.members.unshift(m2);saveData(d);addAudit('Admin created member',m2.id);m.remove();switchAdminModule('Members');toast('Member created.')}}
function showNotificationForm(){const m=modal('Create Notification',`<form id="xform" class="form-grid"><div class="field"><label>Type</label><input name="type" value="GENERAL"></div><div class="field"><label>Channel</label><select name="channel"><option>IN-APP</option><option>EMAIL</option><option>SMS</option><option>WHATSAPP</option></select></div><div class="field full"><label>Message</label><textarea name="message" required></textarea></div><div class="field full"><button class="btn primary">CREATE NOTIFICATION</button></div></form>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),d=getData();d.notifications.unshift({id:uid('NOT'),type:f.get('type'),channel:f.get('channel'),message:f.get('message'),time:new Date().toLocaleString(),read:false});saveData(d);addAudit('Notification created','NOTIFICATION');m.remove();switchAdminModule('Notifications');toast('Notification created.')}}
function showEmailForm(i=null){const d=getData(),t=i!==null?d.emailTemplates[i]:null,m=modal('Email Template',`<form id="xform" class="form-grid"><div class="field"><label>Name</label><input name="name" value="${esc(t?.name||'New template')}" required></div><div class="field"><label>Subject</label><input name="subject" value="${esc(t?.subject||'GLDC notification')}" required></div><div class="field full"><label>Body</label><textarea name="body" rows="8" required>${esc(t?.body||'Hello {{member.name}},')}</textarea></div><div class="field full"><button class="btn primary">SAVE TEMPLATE</button></div></form>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),d2=getData(),obj={id:t?.id||uid('EMAIL'),name:f.get('name'),subject:f.get('subject'),body:f.get('body')};if(t)d2.emailTemplates[i]=obj;else d2.emailTemplates.unshift(obj);saveData(d2);addAudit(t?'Email template updated':'Email template created',obj.id);m.remove();switchAdminModule('Email Center');toast('Email template saved.')}}
function showDocumentForm(projectIndex=0){const d=getData(),p=d.projects[projectIndex]||d.projects[0],docId=uid('DOC'),m=modal('Generate Project PDF Record',`<form id="xform" class="form-grid"><div class="field full"><label>Project</label><select name="project">${d.projects.map(x=>`<option value="${esc(x.id)}" ${x.id===p?.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div><div class="field"><label>Access</label><select name="access"><option>MEMBER-ONLY</option><option>INTERNAL</option><option>PUBLIC</option></select></div><div class="field"><label>Verification</label><select name="verify"><option>REQUIRED</option><option>OPTIONAL</option></select></div><div class="field full"><div class="notice">The generated print view contains an admin signature line, office stamp area and QR verification target. Browser Print → Save as PDF creates the actual PDF file in this static prototype.</div></div><div class="field full"><button class="btn primary">CREATE DOCUMENT RECORD</button></div></form>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),d2=getData(),id=docId,obj={id,name:`${d2.projects.find(x=>x.id===f.get('project'))?.name||'Project'} Proof of Work`,project:f.get('project'),access:f.get('access'),status:'ACTIVE',date:new Date().toISOString().slice(0,10),verify:`verify.html?doc=${encodeURIComponent(id)}`};d2.documents.unshift(obj);saveData(d2);addAudit('Project PDF record generated',id);m.remove();switchAdminModule('Documents & PDFs');toast('Document record created. Open it to print/save as PDF.')}}
function showUserForm(){const m=modal('Add User',`<form id="xform" class="form-grid"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Role</label><select name="role"><option>STAFF</option><option>CONTENT MANAGER</option><option>PROJECT MANAGER</option><option>FINANCE</option><option>MANAGING DIRECTOR</option></select></div><div class="field full"><button class="btn primary">CREATE USER</button></div></form>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),d=getData(),id=uid('USR');d.users.push({id,name:f.get('name'),email:f.get('email'),role:f.get('role'),status:'ACTIVE'});saveData(d);addAudit('User created',id);m.remove();switchAdminModule('Users & Roles');toast('User created.')}}
function bindAdmin(){const root=document.getElementById('adminContent');root.querySelectorAll('[data-admin-action]').forEach(b=>b.onclick=()=>adminAction(b.dataset.adminAction));root.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>switchAdminModule(b.dataset.jump));root.querySelectorAll('[data-lead-approve]').forEach(b=>b.onclick=()=>approveLead(+b.dataset.leadApprove));root.querySelectorAll('[data-lead-reject]').forEach(b=>b.onclick=()=>rejectLead(+b.dataset.leadReject));root.querySelectorAll('[data-lead-edit]').forEach(b=>b.onclick=()=>editLead(+b.dataset.leadEdit));root.querySelectorAll('[data-project-edit]').forEach(b=>b.onclick=()=>showProjectForm(+b.dataset.projectEdit));root.querySelectorAll('[data-project-publish]').forEach(b=>b.onclick=()=>toggleProject(+b.dataset.projectPublish));root.querySelectorAll('[data-project-pdf]').forEach(b=>b.onclick=()=>showDocumentForm(+b.dataset.projectPdf));root.querySelectorAll('[data-service-edit]').forEach(b=>b.onclick=()=>showServiceForm(+b.dataset.serviceEdit));root.querySelectorAll('[data-service-toggle]').forEach(b=>b.onclick=()=>toggleSimple('services',+b.dataset.serviceToggle,'published','Services'));root.querySelectorAll('[data-team-edit]').forEach(b=>b.onclick=()=>showTeamForm(+b.dataset.teamEdit));root.querySelectorAll('[data-team-approve]').forEach(b=>b.onclick=()=>approveTeam(+b.dataset.teamApprove));root.querySelectorAll('[data-test-edit]').forEach(b=>b.onclick=()=>showTestimonialForm(+b.dataset.testEdit));root.querySelectorAll('[data-test-approve]').forEach(b=>b.onclick=()=>approveTest(+b.dataset.testApprove));root.querySelectorAll('[data-media-edit]').forEach(b=>b.onclick=()=>showMediaForm(+b.dataset.mediaEdit));root.querySelectorAll('[data-form-edit]').forEach(b=>b.onclick=()=>showFormBuilder(+b.dataset.formEdit));root.querySelectorAll('[data-form-toggle]').forEach(b=>b.onclick=()=>toggleSimple('forms',+b.dataset.formToggle,'published','Custom Forms'));root.querySelectorAll('[data-notif-read]').forEach(b=>b.onclick=()=>{const d=getData();d.notifications[+b.dataset.notifRead].read=true;saveData(d);switchAdminModule('Notifications')});root.querySelectorAll('[data-email-edit]').forEach(b=>b.onclick=()=>showEmailForm(+b.dataset.emailEdit));root.querySelectorAll('[data-email-send]').forEach(b=>b.onclick=()=>{addAudit('Email simulated send',getData().emailTemplates[+b.dataset.emailSend].id);toast('Email send action recorded. No real email was sent.')});root.querySelectorAll('[data-content-delete]').forEach(b=>b.onclick=()=>{const d=getData();delete d.content[b.dataset.contentDelete];saveData(d);switchAdminModule('Pages & Sections')});root.querySelectorAll('[data-section-edit]').forEach(b=>b.onclick=()=>showSectionForm(+b.dataset.sectionEdit));root.querySelectorAll('[data-section-toggle]').forEach(b=>b.onclick=()=>toggleSimple('sections',+b.dataset.sectionToggle,'published','Pages & Sections'));const sf=root.querySelector('#settingsForm');if(sf)sf.onsubmit=e=>saveSettings(e);}
function adminAction(a){if(a==='new-lead')return showLeadForm();if(a==='new-client')return showClientForm();if(a==='new-project')return showProjectForm();if(a==='new-task')return showTaskForm();if(a==='new-consultation')return showConsultationForm();if(a==='new-quote')return showQuoteForm();if(a==='new-invoice')return showInvoiceForm();if(a==='new-payment')return showPaymentForm();if(a==='new-content')return showContentField();if(a==='new-section')return showSectionForm();if(a==='new-service')return showServiceForm();if(a==='new-team')return showTeamForm();if(a==='new-testimonial')return showTestimonialForm();if(a==='new-media')return showMediaForm();if(a==='new-form')return showFormBuilder();if(a==='new-member')return showMemberForm();if(a==='new-notification')return showNotificationForm();if(a==='new-email')return showEmailForm();if(a==='new-document')return showDocumentForm();if(a==='new-user')return showUserForm();if(a==='save-content'){const d=getData();document.querySelectorAll('[data-content-key]').forEach(x=>d.content[x.dataset.contentKey]=x.value);saveData(d);addAudit('Website CMS content saved','CMS');toast('All editable content saved.');return}if(a==='mark-read'){const d=getData();d.notifications.forEach(n=>n.read=true);saveData(d);switchAdminModule('Notifications');return}if(a==='test-email'){addAudit('Test email action','EMAIL');toast('Test email action recorded. Configure a real provider in production.')}}
function approveLead(i){const d=getData(),l=d.leads[i];l.status='APPROVED';if(!l.depositRequired)l.depositRequired=Number(l.requestedValue||0)*0.2;d.notifications.unshift({id:uid('NOT'),type:'LEAD APPROVED',channel:'IN-APP',message:`${l.id} approved. Member payment gate is now unlocked.`,time:new Date().toLocaleString(),read:false});saveData(d);addAudit('Lead approved',l.id);switchAdminModule('Leads');toast('Lead approved. Member can now see PAY DEPOSIT.')}
function rejectLead(i){const d=getData(),l=d.leads[i];l.status='REJECTED';saveData(d);addAudit('Lead rejected',l.id,'REJECTED');switchAdminModule('Leads');toast('Lead rejected.')}
function editLead(i){const d=getData(),l=d.leads[i],m=modal('Edit Lead',`<form id="xform" class="form-grid"><div class="field"><label>Name</label><input name="name" value="${esc(l.name)}"></div><div class="field"><label>Service</label><input name="service" value="${esc(l.service)}"></div><div class="field"><label>Status</label><select name="status">${['NEW','MEMBER_SUBMITTED','CONTACTED','QUALIFIED','CONSULTATION','PROPOSAL','APPROVED','REJECTED','WON'].map(x=>`<option ${l.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Deposit (KES)</label><input name="deposit" type="number" value="${esc(l.depositRequired||0)}"></div><div class="field full"><button class="btn primary">SAVE LEAD</button></div></form>`);m.querySelector('form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),d2=getData();Object.assign(d2.leads[i],{name:f.get('name'),service:f.get('service'),status:f.get('status'),depositRequired:Number(f.get('deposit'))});saveData(d2);addAudit('Lead updated',d2.leads[i].id);m.remove();switchAdminModule('Leads');toast('Lead updated.')}}
function toggleProject(i){const d=getData(),p=d.projects[i];if(!p.approved){toast('Approve the project before publishing.');return}p.published=!p.published;saveData(d);addAudit(p.published?'Project published':'Project unpublished',p.id);switchAdminModule('Projects');toast('Project publication updated.')}
function approveTeam(i){const d=getData(),t=d.team[i];t.status=t.status==='APPROVED'?'PENDING':'APPROVED';t.published=t.status==='APPROVED';saveData(d);addAudit(t.published?'Team profile approved and published':'Team profile unpublished',t.id);switchAdminModule('Team Approval');toast('Team approval updated.')}
function approveTest(i){const d=getData(),t=d.testimonials[i];t.status=t.status==='APPROVED'?'DRAFT':'APPROVED';t.published=t.status==='APPROVED';saveData(d);addAudit(t.published?'Testimonial approved and published':'Testimonial unpublished',t.id);switchAdminModule('Testimonials');toast('Testimonial approval updated.')}
function toggleSimple(key,i,prop,module){const d=getData();d[key][i][prop]=!d[key][i][prop];saveData(d);addAudit(`${key} ${prop} changed`,d[key][i].id||String(i));switchAdminModule(module);toast('Publication state updated.')}
function saveSettings(e){e.preventDefault();const f=new FormData(e.target),d=getData();if(location.hash.includes('Brand')){for(const k of ['company','shortName','tagline','phone','whatsapp','email','location','hours'])d.settings[k]=f.get(k)}else{d.membership.enabled=f.get('membershipEnabled')==='true';d.membership.buttonLabel=f.get('buttonLabel');d.membership.requiresApproval=f.get('requiresApproval')==='true'}saveData(d);addAudit('Settings updated',location.hash);toast('Settings saved. Refresh the public site to see changes.');}
function renderAdmin(){adminLayout();switchAdminModule(decodeURIComponent(location.hash.replace('#',''))||'Dashboard')}
function legalPage(key,label){const d=getData();shell(`<section class="page-hero"><div class="container"><span class="eyebrow">LEGAL</span><h1>${esc(d.content[key+'.title'])}</h1><p>Editable website legal content.</p></div></section><section class="section"><div class="container"><article class="card"><span class="badge-default">DEFAULT — EDIT IN CMS</span><p style="white-space:pre-wrap">${esc(d.content[key+'.body'])}</p></article></div></section>${publishedSections(key)}`)}
function publicInit(){const p=location.pathname.split('/').pop()||'index.html';if(p==='index.html')homePage();else if(p==='about.html')aboutPage();else if(p==='services.html')servicesPage();else if(p==='service-detail.html')serviceDetail();else if(p==='projects.html')projectsPage();else if(p==='project-detail.html')projectDetail();else if(p==='team.html')teamPage();else if(p==='testimonials.html')testimonialsPage();else if(p==='service-areas.html')areasPage();else if(p==='contact.html')contactPage();else if(p==='quote.html')quotePage();else if(p==='member.html')memberPage();else if(p==='verify.html')verifyPage();else if(p==='document.html')documentPage();else if(p==='form.html')customFormPage();else if(p==='privacy.html')legalPage('privacy','PRIVACY');else if(p==='terms.html')legalPage('terms','TERMS');else shell(pageHero('about','PAGE')+'<section class="section"><div class="container"><div class="notice">Page ready.</div></div></section>')}
document.addEventListener('DOMContentLoaded',()=>{if(document.body.dataset.page==='admin')adminLogin();else if(document.body.dataset.page==='public')publicInit()});
